package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The sheet's settings: its clerk limit (none: no limit) and its floor, the least a claim's live due
 * can be, and its terms, the days after its date a claim is due by, and its late percent, what an
 * overdue claim gains of its figure for every full 30 days overdue. Changing the floor or the late
 * percent moves the figures, so the figures that move are recorded. Its policy date (none:
 * the sheet's today) decides how a claim's live figures round (see {@link Rounding}), so changing it
 * records the figures that move too. Its period-numbering-from date (none: off) decides how a claim
 * opened is numbered: on or after it, within its period (see {@link SheetService#nextClaimNumber}).
 * Its cap (none: no cap) is the most a person's due-total can be, so changing it records the
 * figures that move too. A grade may have its own terms; a grade without uses the sheet's terms. A claim's due-by is fixed
 * when it is created, so changing any terms moves no claim's due-by. A grade may have grace days (none: no grace): a
 * claim whose person's grade on its date has grace days on that date is overdue only once its due-by plus them is
 * before the sheet's today, and its late charge counts its 30-day boundaries from there (see
 * {@link Sheet#lateFrom}); its due-by is unchanged. Changing a grade's grace days moves the figures, so the figures
 * that move are recorded.
 * <p>
 * The settings that carry a figure (the floor, the late percent, the terms, a grade's own terms,
 * a grade's grace days, the clerk limit, the cap, the proof threshold, a grade's own proof threshold and the note threshold) are dated: each value is recorded from a from-date (the sheet's
 * today when none is given). A claim's floor, late percent and terms are those in force on its
 * date, as is its proof threshold (its person's grade's own in force then when it has one, else the sheet's; see {@link Sheet#proofThresholdFor}) and its note threshold (see {@link Sheet#noteThresholdOn}); the clerk limit and the cap are those in force on the sheet's today (see {@link Sheet}).
 * The policy date and the period-numbering-from date are not dated. Nor is the permission matrix:
 * for each of open, settle, void, reassign, close and reopen, the roles that may take it (blank: the
 * standing rule, see {@link Sheet#permits}), recorded under the key {@code perm-<action>}. Nor are
 * the grace days (none: off): when the sheet's today changes, every open period whose to-date plus
 * the grace days is before the new today is closed (see {@link SheetService#setToday}). Nor is the
 * entry date (none: off): while set, it is the default date of a new claim in place of the sheet's today.
 * Nor is the pot (none: no pot), shared out over each balanced pool's members as their cuts (see
 * {@link net.officefloor.hq.app.pool.PoolService}).
 */
@Service
public class SettingService {

    public static final String CLERK_LIMIT = Sheet.CLERK_LIMIT;
    public static final String FLOOR = Sheet.FLOOR;
    public static final String CAP = Sheet.CAP;
    public static final String TERMS = Sheet.TERMS;
    /** The key of a grade's own terms: {@code terms-<grade>}. */
    public static final String GRADE_TERMS = Sheet.GRADE_TERMS;
    /** The key of a grade's grace days: {@code grace-<grade>}. */
    public static final String GRADE_GRACE = Sheet.GRADE_GRACE;
    public static final String LATE_PCT = Sheet.LATE_PCT;
    public static final String PROOF_THRESHOLD = Sheet.PROOF_THRESHOLD;
    public static final String NOTE_THRESHOLD = Sheet.NOTE_THRESHOLD;
    /** The key of a grade's own proof threshold: {@code proof-threshold-<grade>}. */
    public static final String GRADE_PROOF_THRESHOLD = Sheet.GRADE_PROOF_THRESHOLD;
    public static final String POLICY_DATE = "policy-date";
    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";
    public static final String GRACE_DAYS = "grace-days";
    public static final String ENTRY_DATE = "entry-date";
    public static final String POT = "pot";
    /** The key of a permission matrix entry: {@code perm-<action>}. */
    public static final String PERMISSION = "perm-";

    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final RollupService rollup;
    private final Audit audit;
    private final RoleService roles;

    public SettingService(SheetService sheets, SheetRepository sheetStore, RollupService rollup, Audit audit,
            RoleService roles) {
        this.roles = roles;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.rollup = rollup;
        this.audit = audit;
    }

    @Transactional
    public Sheet get(String sheetId, String user) {
        return sheets.load(sheetId, user);
    }

    /**
     * A value to record for a setting that carries a figure (null for none: no limit, no cap) from
     * a from-date (null: from the sheet's today, and the record names no from-date).
     */
    public record Dated<T>(T value, LocalDate from) {
    }

    /**
     * Save the settings given: a clerk limit when {@code limit} is not null, and the floor, the
     * terms and the late percent when they are not null, and a policy date when {@code changePolicy}
     * (null for none), and a period-numbering-from date when {@code changeNumbering} (null for off),
     * and a cap when {@code cap} is not null, and each grade's own terms given in {@code gradeTerms}
     * (by grade, in grade order), and each grade's grace days given in {@code gradeGraces} (by grade, in grade
     * order; null for none), and a proof threshold when {@code proofThreshold} is not null, and each grade's own proof
     * threshold given in {@code gradeProofThresholds} (by grade, in grade order; null for none), and a note threshold when
     * {@code noteThreshold} is not null, and each permission matrix entry
     * given in {@code permissions} (by action, in the order given; blank for the standing rule), and the grace days when
     * {@code changeGrace} (null for off), and the entry date when {@code changeEntry} (null for off), and the pot when {@code changePot} (null for none). Each figure is recorded from its from-date, keeping the values
     * already recorded (one already recorded from that date is replaced). Each one saved is
     * recorded, in that order.
     */
    @Transactional
    public Sheet set(String sheetId, String user, Dated<BigDecimal> limit, Dated<BigDecimal> floor,
            Dated<Integer> terms, Dated<BigDecimal> latePct, boolean changePolicy, LocalDate policyDate,
            boolean changeNumbering, LocalDate numberingFrom, Dated<BigDecimal> cap,
            Map<String, Dated<Integer>> gradeTerms, Map<String, Dated<Integer>> gradeGraces,
            Dated<BigDecimal> proofThreshold, Map<String, Dated<BigDecimal>> gradeProofThresholds,
            Dated<BigDecimal> noteThreshold, Map<String, String> permissions,
            boolean changeGrace, Integer graceDays, boolean changeEntry, LocalDate entryDate,
            boolean changePot, BigDecimal pot) {
        roles.refuseViewer(sheetId, user);
        Sheet sheet = sheets.load(sheetId, user);
        if (limit != null) {
            sheet = record(sheet, user, CLERK_LIMIT, limit.value(), limit.from(), text(limit.value()), false);
        }
        if (floor != null) {
            sheet = record(sheet, user, FLOOR, floor.value(), floor.from(), text(floor.value()), true);
        }
        if (terms != null) {
            sheet = record(sheet, user, TERMS, BigDecimal.valueOf(terms.value()), terms.from(),
                    String.valueOf(terms.value()), false);
        }
        if (latePct != null) {
            sheet = record(sheet, user, LATE_PCT, latePct.value(), latePct.from(), text(latePct.value()), true);
        }
        if (changePolicy) {
            RollupService.Snapshot before = rollup.snapshot(sheetId);
            sheet.setPolicyDate(policyDate);
            sheet = sheetStore.saveAndFlush(sheet);
            audit.recordOnCommit(changed(sheetId, user, POLICY_DATE, policyDate == null ? "" : policyDate.toString()));
            rollup.recordChanges(sheetId, user, before);
        }
        if (changeNumbering) {
            sheet.setPeriodNumberingFrom(numberingFrom);
            sheet = sheetStore.saveAndFlush(sheet);
            audit.recordOnCommit(changed(sheetId, user, PERIOD_NUMBERING_FROM,
                    numberingFrom == null ? "" : numberingFrom.toString()));
        }
        if (cap != null) {
            sheet = record(sheet, user, CAP, cap.value(), cap.from(), text(cap.value()), true);
        }
        for (Map.Entry<String, Dated<Integer>> e : new TreeMap<>(gradeTerms).entrySet()) {
            Dated<Integer> t = e.getValue();
            sheet = record(sheet, user, GRADE_TERMS + e.getKey(), BigDecimal.valueOf(t.value()), t.from(),
                    String.valueOf(t.value()), false);
        }
        for (Map.Entry<String, Dated<Integer>> e : new TreeMap<>(gradeGraces).entrySet()) {
            Dated<Integer> g = e.getValue();
            sheet = record(sheet, user, GRADE_GRACE + e.getKey(), g.value() == null ? null : BigDecimal.valueOf(g.value()),
                    g.from(), g.value() == null ? "" : String.valueOf(g.value()), true);
        }
        if (proofThreshold != null) {
            sheet = record(sheet, user, PROOF_THRESHOLD, proofThreshold.value(), proofThreshold.from(),
                    text(proofThreshold.value()), false);
        }
        for (Map.Entry<String, Dated<BigDecimal>> e : new TreeMap<>(gradeProofThresholds).entrySet()) {
            Dated<BigDecimal> t = e.getValue();
            sheet = record(sheet, user, GRADE_PROOF_THRESHOLD + e.getKey(), t.value(), t.from(), text(t.value()), false);
        }
        if (noteThreshold != null) {
            sheet = record(sheet, user, NOTE_THRESHOLD, noteThreshold.value(), noteThreshold.from(),
                    text(noteThreshold.value()), false);
        }
        for (Map.Entry<String, String> e : permissions.entrySet()) {
            sheet.setPermission(e.getKey(), e.getValue());
            sheet = sheetStore.saveAndFlush(sheet);
            audit.recordOnCommit(changed(sheetId, user, PERMISSION + e.getKey(), e.getValue()));
        }
        if (changeGrace) {
            sheet.setGraceDays(graceDays);
            sheet = sheetStore.saveAndFlush(sheet);
            audit.recordOnCommit(changed(sheetId, user, GRACE_DAYS, graceDays == null ? "" : graceDays.toString()));
        }
        if (changeEntry) {
            sheet.setEntryDate(entryDate);
            sheet = sheetStore.saveAndFlush(sheet);
            audit.recordOnCommit(changed(sheetId, user, ENTRY_DATE, entryDate == null ? "" : entryDate.toString()));
        }
        if (changePot) {
            sheet.setPot(pot == null ? null : pot.setScale(2));
            sheet = sheetStore.saveAndFlush(sheet);
            audit.recordOnCommit(changed(sheetId, user, POT, text(sheet.getPot())));
        }
        return sheet;
    }

    /**
     * Record a setting's value from a from-date (null: the sheet's today) and audit it; when it
     * {@code moves} the figures, the figures that move are recorded too.
     */
    private Sheet record(Sheet sheet, String user, String key, BigDecimal value, LocalDate from, String text,
            boolean moves) {
        String sheetId = sheet.getId();
        RollupService.Snapshot before = moves ? rollup.snapshot(sheetId) : null;
        sheet.record(key, from != null ? from : sheet.getToday(), value);
        Sheet saved = sheetStore.saveAndFlush(sheet);
        audit.recordOnCommit(changed(sheetId, user, key, text) + (from != null ? " from=" + from : ""));
        if (moves) {
            rollup.recordChanges(sheetId, user, before);
        }
        return saved;
    }

    private static String changed(String sheetId, String user, String key, String value) {
        return "SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key + " value=" + value;
    }

    /** A limit with two decimals, or blank for none. */
    public static String text(BigDecimal limit) {
        return limit == null ? "" : limit.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.ClaimController;
import net.officefloor.hq.app.sheet.DatedSetting;
import net.officefloor.hq.app.sheet.Sheet;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/** Reading and saving the sheet's settings. */
@RestController
@RequestMapping("/api/settings")
public class SettingController {

    /** A late percent: 0.00 to 999.99, with up to two decimals. */
    private static final String LATE_PCT = "\\d{1,3}(\\.\\d{1,2})?";

    /** Terms: a whole number of days. */
    private static final String TERMS = "\\s*\\d{1,4}\\s*";

    /** A date setting: yyyy-mm-dd, or blank for none. */
    private static final String DATE = "\\s*|\\s*\\d{4}-\\d{2}-\\d{2}\\s*";

    /** A permission matrix entry: roles (clerk, steward) comma separated, or blank for the standing rule. */
    private static final String ROLES = "\\s*|\\s*(?i:clerk|steward)(\\s*,\\s*(?i:clerk|steward))*\\s*";

    public record GetSettingsRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user) {
    }

    /**
     * The settings to save; a setting left null is left as it is. A clerk limit: an amount with up
     * to two decimals, or blank for no limit. A floor: an amount with up to two decimals. Terms: a
     * whole number of days. A late percent: 0.00 to 999.99, with up to two decimals. A policy date:
     * yyyy-mm-dd, or blank for none (the sheet's today). A period-numbering-from date: yyyy-mm-dd,
     * or blank for off. A grade's own terms (A, B or C): a whole number of days. A cap: an amount with
     * up to two decimals, or blank for none. A proof threshold: an amount with up to two decimals, or blank
     * for none. A note threshold: an amount with up to two decimals, or blank for none. A permission matrix entry for open, settle, void, reassign, close or reopen: roles
     * comma separated, or blank for the standing rule. Grace days: a whole number of days, or blank for off. A grade's grace days (A, B or C): a whole number of days, or blank for none. A grade's own proof threshold (A, B or C): an amount with up to two decimals, or blank for none (the sheet's). An entry date: yyyy-mm-dd, or blank for off. A pot: an amount with up to two decimals, or blank for none. Each setting that carries a figure may name the date it
     * is in force from (its {@code ...From}: yyyy-mm-dd, or blank or null for the sheet's today).
     */
    public record SetSettingsRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @Pattern(regexp = "\\s*|" + ClaimController.AMOUNT) String clerkLimit,
            @Pattern(regexp = ClaimController.AMOUNT) String floor,
            @Pattern(regexp = TERMS) String terms,
            @Pattern(regexp = LATE_PCT) String latePct,
            @Pattern(regexp = DATE) String policyDate, @Pattern(regexp = DATE) String periodNumberingFrom,
            @Pattern(regexp = TERMS) String termsA, @Pattern(regexp = TERMS) String termsB,
            @Pattern(regexp = TERMS) String termsC, @Pattern(regexp = "\\s*|" + ClaimController.AMOUNT) String cap,
            @Pattern(regexp = DATE) String clerkLimitFrom, @Pattern(regexp = DATE) String floorFrom,
            @Pattern(regexp = DATE) String termsFrom, @Pattern(regexp = DATE) String latePctFrom,
            @Pattern(regexp = DATE) String termsAFrom, @Pattern(regexp = DATE) String termsBFrom,
            @Pattern(regexp = DATE) String termsCFrom, @Pattern(regexp = DATE) String capFrom,
            @Pattern(regexp = "\\s*|" + ClaimController.AMOUNT) String proofThreshold,
            @Pattern(regexp = DATE) String proofThresholdFrom,
            @Pattern(regexp = "\\s*|" + ClaimController.AMOUNT) String noteThreshold,
            @Pattern(regexp = DATE) String noteThresholdFrom,
            @Pattern(regexp = ROLES) String permOpen, @Pattern(regexp = ROLES) String permSettle,
            @Pattern(regexp = ROLES) String permVoid, @Pattern(regexp = ROLES) String permReassign,
            @Pattern(regexp = ROLES) String permClose, @Pattern(regexp = ROLES) String permReopen,
            @Pattern(regexp = "\\s*|" + TERMS) String graceDays, @Pattern(regexp = DATE) String entryDate,
            @Pattern(regexp = "\\s*|" + TERMS) String graceA, @Pattern(regexp = "\\s*|" + TERMS) String graceB,
            @Pattern(regexp = "\\s*|" + TERMS) String graceC, @Pattern(regexp = DATE) String graceAFrom,
            @Pattern(regexp = DATE) String graceBFrom, @Pattern(regexp = DATE) String graceCFrom,
            @Pattern(regexp = "\\s*|" + ClaimController.AMOUNT) String proofThresholdA,
            @Pattern(regexp = "\\s*|" + ClaimController.AMOUNT) String proofThresholdB,
            @Pattern(regexp = "\\s*|" + ClaimController.AMOUNT) String proofThresholdC,
            @Pattern(regexp = DATE) String proofThresholdAFrom, @Pattern(regexp = DATE) String proofThresholdBFrom,
            @Pattern(regexp = DATE) String proofThresholdCFrom,
            @Pattern(regexp = "\\s*|" + ClaimController.AMOUNT) String pot) {
    }

    /** A value recorded for a setting that carries a figure: blank from for the beginning of time, blank value for none. */
    public record DatedValue(String key, String from, String value) {
    }

    /**
     * The settings in force on the sheet's today; the clerk limit blank for none, the policy date
     * blank for none, the period-numbering-from date blank for off, the cap blank for none, the proof threshold blank for none, the note threshold blank for none; the terms
     * in force for each grade that has its own. And every value recorded for the settings that carry
     * a figure, by key and from-date. And the permission matrix: for each action, its roles as
     * entered, blank for the standing rule. And the grace days, blank for off. And the entry date, blank for off.
     * And the pot, blank for none.
     */
    public record SettingsResponse(String clerkLimit, String floor, int terms, String latePct, String policyDate,
            String periodNumberingFrom, Map<String, Integer> gradeTerms, String cap, String proofThreshold,
            String noteThreshold,
            List<DatedValue> dated, Map<String, String> permissions, String graceDays, String entryDate, String pot) {
    }

    private static SettingsResponse response(Sheet sheet) {
        return new SettingsResponse(SettingService.text(sheet.getClerkLimit()), SettingService.text(sheet.getFloor()),
                sheet.getTerms(), SettingService.text(sheet.getLatePct()),
                sheet.getPolicyDate() == null ? "" : sheet.getPolicyDate().toString(),
                sheet.getPeriodNumberingFrom() == null ? "" : sheet.getPeriodNumberingFrom().toString(),
                sheet.getGradeTerms(), SettingService.text(sheet.getCap()), SettingService.text(sheet.getProofThreshold()),
                SettingService.text(sheet.getNoteThreshold()),
                sheet.getSettings().stream().map(SettingController::dated).toList(), sheet.getPermissions(),
                sheet.getGraceDays() == null ? "" : String.valueOf(sheet.getGraceDays()),
                sheet.getEntryDate() == null ? "" : sheet.getEntryDate().toString(), SettingService.text(sheet.getPot()));
    }

    private static DatedValue dated(DatedSetting s) {
        String value = s.getValue() == null ? ""
                : s.getKey().startsWith(SettingService.TERMS) || s.getKey().startsWith(SettingService.GRADE_GRACE) ? String.valueOf(s.getValue().intValue())
                : SettingService.text(s.getValue());
        return new DatedValue(s.getKey(), s.getFromDate() == null ? "" : s.getFromDate().toString(), value);
    }

    private final SettingService service;

    public SettingController(SettingService service) {
        this.service = service;
    }

    @PostMapping("/get")
    public SettingsResponse get(@Valid @RequestBody GetSettingsRequest req) {
        return response(service.get(req.sheet().trim(), req.user().trim()));
    }

    @PostMapping("/set")
    public SettingsResponse set(@Valid @RequestBody SetSettingsRequest req) {
        String policy = req.policyDate() == null ? "" : req.policyDate().trim();
        String numberingFrom = req.periodNumberingFrom() == null ? "" : req.periodNumberingFrom().trim();
        Map<String, SettingService.Dated<Integer>> gradeTerms = new TreeMap<>();
        if (req.termsA() != null) gradeTerms.put("A", terms(req.termsA(), req.termsAFrom()));
        if (req.termsB() != null) gradeTerms.put("B", terms(req.termsB(), req.termsBFrom()));
        if (req.termsC() != null) gradeTerms.put("C", terms(req.termsC(), req.termsCFrom()));
        Map<String, SettingService.Dated<Integer>> gradeGraces = new TreeMap<>();
        if (req.graceA() != null) gradeGraces.put("A", grace(req.graceA(), req.graceAFrom()));
        if (req.graceB() != null) gradeGraces.put("B", grace(req.graceB(), req.graceBFrom()));
        if (req.graceC() != null) gradeGraces.put("C", grace(req.graceC(), req.graceCFrom()));
        Map<String, SettingService.Dated<BigDecimal>> gradeProofThresholds = new TreeMap<>();
        if (req.proofThresholdA() != null) gradeProofThresholds.put("A", amount(req.proofThresholdA(), req.proofThresholdAFrom()));
        if (req.proofThresholdB() != null) gradeProofThresholds.put("B", amount(req.proofThresholdB(), req.proofThresholdBFrom()));
        if (req.proofThresholdC() != null) gradeProofThresholds.put("C", amount(req.proofThresholdC(), req.proofThresholdCFrom()));
        Map<String, String> permissions = new LinkedHashMap<>();
        permission(permissions, "open", req.permOpen());
        permission(permissions, "settle", req.permSettle());
        permission(permissions, "void", req.permVoid());
        permission(permissions, "reassign", req.permReassign());
        permission(permissions, "close", req.permClose());
        permission(permissions, "reopen", req.permReopen());
        String grace = req.graceDays() == null ? "" : req.graceDays().trim();
        String entry = req.entryDate() == null ? "" : req.entryDate().trim();
        String pot = req.pot() == null ? "" : req.pot().trim();
        return response(service.set(req.sheet().trim(), req.user().trim(),
                req.clerkLimit() == null ? null : amount(req.clerkLimit(), req.clerkLimitFrom()),
                req.floor() == null ? null : amount(req.floor(), req.floorFrom()),
                req.terms() == null ? null : terms(req.terms(), req.termsFrom()),
                req.latePct() == null ? null : amount(req.latePct(), req.latePctFrom()), req.policyDate() != null,
                policy.isEmpty() ? null : date(policy), req.periodNumberingFrom() != null,
                numberingFrom.isEmpty() ? null : date(numberingFrom),
                req.cap() == null ? null : amount(req.cap(), req.capFrom()), gradeTerms, gradeGraces,
                req.proofThreshold() == null ? null : amount(req.proofThreshold(), req.proofThresholdFrom()), gradeProofThresholds,
                req.noteThreshold() == null ? null : amount(req.noteThreshold(), req.noteThresholdFrom()), permissions,
                req.graceDays() != null, grace.isEmpty() ? null : Integer.valueOf(grace),
                req.entryDate() != null, entry.isEmpty() ? null : date(entry),
                req.pot() != null, pot.isEmpty() ? null : ClaimController.amount(pot)));
    }

    /** A permission matrix entry given: its roles, lower case, comma separated without spaces. */
    private static void permission(Map<String, String> permissions, String action, String roles) {
        if (roles != null) {
            permissions.put(action, roles.trim().isEmpty() ? ""
                    : String.join(",", Arrays.stream(roles.trim().split("\\s*,\\s*")).map(r -> r.toLowerCase(Locale.ROOT)).toList()));
        }
    }

    /** An amount (blank: none) from a from-date (blank or null: the sheet's today). */
    private static SettingService.Dated<BigDecimal> amount(String value, String from) {
        String text = value.trim();
        return new SettingService.Dated<>(text.isEmpty() ? null : ClaimController.amount(text), from(from));
    }

    /** Terms from a from-date (blank or null: the sheet's today). */
    private static SettingService.Dated<Integer> terms(String value, String from) {
        return new SettingService.Dated<>(Integer.valueOf(value.trim()), from(from));
    }

    /** Grace days (blank: none) from a from-date (blank or null: the sheet's today). */
    private static SettingService.Dated<Integer> grace(String value, String from) {
        String text = value.trim();
        return new SettingService.Dated<>(text.isEmpty() ? null : Integer.valueOf(text), from(from));
    }

    private static LocalDate from(String text) {
        return text == null || text.isBlank() ? null : date(text.trim());
    }

    private static LocalDate date(String text) {
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not a date: " + text + ".");
        }
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's rates for each grade: set (or set again) on the screen, one per grade and from-date;
 * setting a grade's rate for a from-date it already has replaces that rate (and its to-date). A
 * to-date before the from-date is refused.
 */
@Service
public class RateService {

    private final RateRepository rates;
    private final RateLogRepository rateLog;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final RoleService roles;

    public RateService(RateRepository rates, RateLogRepository rateLog, SheetService sheets, Audit audit,
            RollupService rollup, RoleService roles) {
        this.rateLog = rateLog;
        this.roles = roles;
        this.rollup = rollup;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
    }

    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate fromDate, LocalDate toDate,
            BigDecimal pct) {
        roles.refuseViewer(sheetId, user);
        if (toDate != null && fromDate != null && toDate.isBefore(fromDate)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A rate's to-date cannot be before its from-date.");
        }
        sheets.load(sheetId, user);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Rate rate = rates.findBySheetIdAndGradeAndFrom(sheetId, grade, fromDate)
                .orElseGet(() -> new Rate(sheetId, grade, fromDate, pct));
        rate.setPct(pct);
        rate.setToDate(toDate);
        Rate saved;
        try {
            saved = rates.saveAndFlush(rate);
        } catch (DataIntegrityViolationException e) {
            // another user set this grade's rate from this date at the same moment
            throw new ResponseStatusException(HttpStatus.CONFLICT, "This rate was just set by someone else.");
        }
        rateLog.saveAndFlush(new RateLog(saved, sheets.today(sheetId)));
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade + " rate="
                + saved.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + (fromDate != null ? " from=" + fromDate : "") + (toDate != null ? " to=" + toDate : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}

