        }
      </p>
      <p>
        Pot:
        <strong data-testid="setting-pot-current">{{ pot() }}</strong>
        @if (pot() === '') {
          <span>(none)</span>
        }
      </p>
      @for (a of permActions; track a) {
        <p>
