          <strong [attr.data-testid]="'setting-perm-' + a + '-current'">{{ permissions()[a] ?? '' }}</strong>
          @if (!permissions()[a]) {
            <span>(the standing rule)</span>
          }
        </p>
      }
    </section>
  `,
})

